# Hypothesis: instantiating an ABC with unimplemented abstract members is a static error and a runtime TypeError, while Shape.register(Blob) makes isinstance succeed at runtime but leaves Blob unrelated to Shape for type checkers.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int:
        raise NotImplementedError

    @abstractmethod
    def area(self) -> float:
        raise NotImplementedError


class Square(Shape):
    def __init__(self, side: float) -> None:
        self._side = side

    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return self._side * self._side


class Blob:
    def area(self) -> float:
        return 0.0


Shape.register(Blob)


def describe(shape: Shape) -> float:
    return shape.area()


def try_make() -> str:
    try:
        Shape()  # expect-error
    except TypeError:
        return "abstract"
    return "concrete"


def check_blob() -> float:
    return describe(Blob())  # expect-error


reveal_type(Square(2.0).sides)
assert describe(Square(2.0)) == 4.0
assert isinstance(Blob(), Shape)
assert check_blob() == 0.0
assert try_make() == "abstract"
